#ifndef MEP_LISP_LSP_CL_NAMES_H
#define MEP_LISP_LSP_CL_NAMES_H

#include <cstddef>

// The interface to src/lisp_lsp_cl_names.cpp, which is generated by
// scripts/gen_cl_names.py out of a live SBCL image. See that script's
// header for why it is generated rather than written: the COMMON-LISP
// package's 978 external symbols are a fixed, standardized set, and a
// lambda list remembered wrongly turns into a wrong-argument-count report
// against a correct call.

// One external symbol of COMMON-LISP, as the generator found it.
struct LispClDecl {
    const char *name;  // upper case, as the reader interns it: "MAKE-HASH-TABLE"
    // Comma-separated roles, most operator-like first: "function",
    // "macro", "special-operator", "generic-function", "variable",
    // "constant", "class", "type", "declaration", "lambda-list-keyword",
    // "optimize-quality", "situation", "symbol". `LIST` is
    // "function,class"; `T` is "constant,class".
    const char *kinds;
    // The operator's lambda list without its outer parentheses,
    // downcased and with SBCL's internal package prefixes stripped:
    // "key hash-table &optional default". "" for a non-operator, and for
    // an operator that takes no arguments.
    const char *lambda_list;
    const char *doc;  // the docstring's first paragraph, or ""
};

// Every external symbol, sorted by byte comparison of `name`.
extern const LispClDecl kLispClDecls[];
extern const size_t kLispClDeclCount;

#endif  // MEP_LISP_LSP_CL_NAMES_H
